from pathlib import Path
import json,re,base64
DATA=json.loads('{"image": "", "css": "<style id=\\"real-bauble-css\\">\\n#kerst-kortingsbal{position:fixed;top:auto;left:auto;right:18px;bottom:20px;width:175px;height:175px;z-index:900;filter:drop-shadow(3px 9px 7px #0005);animation:real-bauble-drop 3s both;isolation:isolate}\\n#kerst-kortingsbal[hidden]{display:none!important}\\n#kerst-kortingsbal::before,#kerst-kortingsbal::after{display:none!important}\\n#kerst-kortingsbal .discount-ball{position:relative;inset:auto;display:block;width:100%;height:100%;padding:0;border:0;border-radius:0;background:none;box-shadow:none;filter:none;animation:real-bauble-sway 6s ease-in-out 3s infinite alternate;transform-origin:50% 5%;color:#fff7e6;text-decoration:none}\\n#kerst-kortingsbal .discount-ball::before,#kerst-kortingsbal .discount-ball::after{display:none!important}\\n#kerst-kortingsbal .real-bauble-image{display:block;width:100%;height:100%;object-fit:contain}\\n#kerst-kortingsbal .discount-copy{position:absolute;left:49%;top:43%;transform:translate(-50%,-50%);z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:0;width:90px;line-height:1.05;text-align:center;color:#fff8e6;text-shadow:0 1px 3px #520313,0 0 6px #520313;font-family:inherit;animation:none}\\n#kerst-kortingsbal .discount-copy strong{font-size:13px;letter-spacing:.12em;color:inherit}\\n#kerst-kortingsbal .discount-copy b{font-size:33px;margin:1px 0;color:inherit;line-height:1}\\n#kerst-kortingsbal .discount-copy span{font-size:14px;color:inherit}\\n#kerst-kortingsbal .discount-close{position:absolute;top:5px;right:0;width:26px;height:26px;border:1px solid #e9d9c4;background:#263243e8;border-radius:50%;color:white;font:20px/1 sans-serif;cursor:pointer;z-index:4}\\n#kerst-kortingsbal :focus-visible{outline:3px solid #8ce1e4;outline-offset:3px}\\n#kerst-kortingsbal .real-light{position:absolute;width:5px;height:5px;border-radius:50%;background:var(--glow);box-shadow:0 0 5px 2px var(--glow);pointer-events:none;animation:real-light-glow 2.8s ease-in-out infinite alternate;opacity:.3}\\n#kerst-kortingsbal .light-red{left:17%;top:65%;--glow:#ff4054}\\n#kerst-kortingsbal .light-green{left:28%;top:79%;--glow:#4cff6a;animation-delay:-.8s}\\n#kerst-kortingsbal .light-gold{left:49%;top:81%;--glow:#ffc845;animation-delay:-1.6s}\\n#kerst-kortingsbal .light-blue{left:69%;top:74%;--glow:#4aafff;animation-delay:-2.2s}\\n@keyframes real-light-glow{from{opacity:.15}to{opacity:.8}}\\n@keyframes real-bauble-drop{0%{transform:translateY(calc(-100vh - 200px)) rotate(-9deg)}48%{transform:translateY(0) rotate(4deg)}65%{transform:translateY(-95px) rotate(-4deg)}78%{transform:translateY(0)}87%{transform:translateY(-30px) rotate(2deg)}94%{transform:translateY(0)}97%{transform:translateY(-8px)}100%{transform:translateY(0)}}\\n@keyframes real-bauble-sway{from{transform:rotate(-2deg)}to{transform:rotate(2deg)}}\\n@media(max-width:700px){#kerst-kortingsbal{width:145px;height:145px;right:10px;bottom:15px}#kerst-kortingsbal .discount-copy strong{font-size:11px}#kerst-kortingsbal .discount-copy b{font-size:28px}#kerst-kortingsbal .discount-copy span{font-size:12px}}\\n@media(prefers-reduced-motion:reduce){#kerst-kortingsbal,#kerst-kortingsbal .discount-ball,#kerst-kortingsbal .real-light{animation:none}}\\n</style>", "markup": "<aside id=\\"kerst-kortingsbal\\" class=\\"discount-bauble\\" aria-label=\\"Kerst: 5% korting\\" hidden><button class=\\"discount-close\\" type=\\"button\\" aria-label=\\"Kerstactie sluiten\\">×</button><a class=\\"discount-ball\\" href=\\"winkel.html\\"><img class=\\"real-bauble-image\\" src=\\"kerstbal-glitter-3d.webp\\" alt=\\"\\" width=\\"1254\\" height=\\"1254\\"><span class=\\"discount-copy\\"><strong>KERST</strong><b>5%</b><span>korting</span></span><span class=\\"real-light light-red\\" aria-hidden=\\"true\\"></span><span class=\\"real-light light-green\\" aria-hidden=\\"true\\"></span><span class=\\"real-light light-gold\\" aria-hidden=\\"true\\"></span><span class=\\"real-light light-blue\\" aria-hidden=\\"true\\"></span></a></aside>", "js": "<script id=\\"kerst-kortingsbal-js\\">(()=>{const ball=document.getElementById(\'kerst-kortingsbal\');if(!ball)return;let dismissed=false;try{dismissed=sessionStorage.getItem(\'kerst-kortingsbal-3d-dicht\')===\'1\';}catch(e){}if(!dismissed)ball.hidden=false;ball.querySelector(\'.discount-close\').addEventListener(\'click\',()=>{ball.hidden=true;try{sessionStorage.setItem(\'kerst-kortingsbal-3d-dicht\',\'1\');}catch(e){}});})();</script>"}')
p=Path('index.html')
if not p.exists(): raise SystemExit('Open eerst de map makers-3d-labs.')
s=p.read_text(encoding='utf-8')
if '</head>' not in s or '</body>' not in s: raise SystemExit('Homepage niet herkend. Niets gewijzigd.')
Path('index.html.before-real-bauble.bak').write_bytes(p.read_bytes())
s=re.sub(r'<aside id="kerst-kortingsbal".*?</aside>','',s,flags=re.S)
s=re.sub(r'<script id="kerst-kortingsbal-js">.*?</script>','',s,flags=re.S)
s=re.sub(r'<style id="real-bauble-css">.*?</style>','',s,flags=re.S)
s=s.replace('</head>',DATA['css']+'</head>').replace('</body>',DATA['markup']+DATA['js']+'</body>')
Path('kerstbal-glitter-3d.webp').write_bytes(base64.b64decode(DATA['image']))
p.write_text(s,encoding='utf-8')
print('Klaar: realistische glitterkerstbal rechts met uitsluitend KERST 5% korting. Nog niet gepubliceerd.')
